def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1
    for i in range(n-1, -1, -1):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1
            break
    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(max(0, i + j - N + 1), min(i + 1, N)):
                l = i + j - k
                if k < 0 or l < 0 or k >= N or l >= N:
                    continue
                if i > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j])
                if j > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[i][j])
                if k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1] + grid[k][l])
                if l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k][l-1] + grid[k][l])
                if i > 0 and k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][j] + grid[k][l])
                if i > 0 and l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j] + grid[k][l])
                if j > 0 and k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + grid[i][j] + grid[k][l])
                if j > 0 and l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[i][j] + grid[k][l])
                if i > 0 and j > 0 and k > 0 and l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j-1][k-1] + grid[i][j] + grid[k][l])

    # The result is the maximum value in dp[N-1][N-1][k] for any k
    return max(dp[N-1][N-1])

