def sum_of_factorials_optimized(n: int) -> int:
    if n < 1 or n > 50:
        raise ValueError("n must be between 1 and 50, inclusive")

    factorial = 1
    sum_factorials = 0

    for i in range(1, n + 1):
        factorial *= i
        sum_factorials += factorial

