def cantor_numbering(N: int) -> str:
    level = 1
    while N > level:
        N -= level
        level += 1
    if level % 2 == 0:
        numerator = N
        denominator = level - N + 1
    else:
        numerator = level - N + 1
        denominator = N
    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    def split_and_multiply(parts):
        product = 1
        for part in parts:
            product *= int(part)
        return product

    def backtrack(start, k, current_parts):
        if k == 0:
            current_parts.append(num_str[start:])
            max_product = split_and_multiply(current_parts)
            current_parts.pop()
            return max_product

        max_product = 0
        for i in range(start + 1, N - k + 2):
            current_parts.append(num_str[start:i])
            max_product = max(max_product, backtrack(i, k - 1, current_parts))
            current_parts.pop()

        return max_product

    return backtrack(0, K, [])

