def count_passing_ways(n: int, m: int) -> int:
    MOD = 10**9 + 7
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = (dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]) % MOD

    return dp[m][0]

def max_energy(beads):
    n = len(beads)
    beads = beads + beads  # Duplicate the list to handle the circular nature
    dp = [[0] * (n * 2) for _ in range(n * 2)]

    for length in range(2, n + 1):
        for i in range(n * 2 - length + 1):
            j = i + length - 1
            for k in range(i + 1, j + 1):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return max(dp[i][i + n - 1] for i in range(n))

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''
        if not terms:
            terms.append(f'{coeff_str}{var_str}')
        else:
            terms.append(f'{sign}{coeff_str}{var_str}')
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != len(set(original)):
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def count_partitions(n: int, k: int, x: int) -> int:
    # Base cases
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0

    # Recursive case
    count = 0
    for i in range(x, n - (k - 1) * x + 1):
        count += count_partitions(n - i, k - 1, i)

    return count

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last == 1:
        return 1
    if last in memo:
        return memo[last]

    count = 1  # Count the sequence consisting of just the number 'last'
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[last] = count
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, tgt in rules:
            start = 0
            while start <= len(current) - len(src):
                pos = current.find(src, start)
                if pos != -1:
                    new_string = current[:pos] + tgt + current[pos + len(src):]
                    if new_string == B:
                        return steps + 1
                    if new_string not in visited:
                        visited.add(new_string)
                        queue.append((new_string, steps + 1))
                else:
                    break
                start = pos + 1

    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a mapping of each digit to its possible transformations
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[x].add(y)
        transform_map[y].add(x)

    # Convert the number to a string for easy manipulation
    original_str = str(n)
    queue = deque([original_str])
    visited = set([original_str])

    while queue:
        current_str = queue.popleft()
        for i in range(len(current_str)):
            current_digit = int(current_str[i])
            if current_digit in transform_map:
                for new_digit in transform_map[current_digit]:
                    new_str = current_str[:i] + str(new_digit) + current_str[i+1:]
                    if new_str not in visited:
                        visited.add(new_str)
                        queue.append(new_str)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, participant_statements in statements.items():
        for statement in participant_statements:
            if statement in days_of_week:
                continue  # Ignore statements about the day of the week
            if participant in liar_count:
                # If the participant is a liar, their statement should be false
                if (statement == "I am guilty." and participant == scenario) or \
                   (statement == "I am not guilty." and participant != scenario) or \
                   (f"{scenario} is guilty." in statement and participant != scenario) or \
                   (f"{scenario} is not guilty." in statement and participant == scenario):
                    continue  # Liar's false statement, continue
                else:
                    return False  # Liar's true statement, scenario is inconsistent
            else:
                # If the participant is not a liar, their statement should be true
                if (statement == "I am guilty." and participant == scenario) or \
                   (statement == "I am not guilty." and participant != scenario) or \
                   (f"{scenario} is guilty." in statement and participant == scenario) or \
                   (f"{scenario} is not guilty." in statement and participant != scenario):
                    continue  # Truth-teller's true statement, continue
                else:
                    return False  # Truth-teller's false statement, scenario is inconsistent
    return True  # All statements are consistent with the scenario

def calculate_score(system: int, points: str) -> list:
    game_scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        # Check if the game is finished
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If there's an ongoing game, add its current score
    if player_score > 0 or opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

