def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a list to store the maximum value that can be obtained for each time limit
    dp = [0] * (T + 1)

    # Iterate over each herb
    for time, value in herbs:
        # Update the dp array from right to left to avoid using the same herb multiple times
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    # The maximum value that can be obtained with the given time limit is stored in dp[T]
    return dp[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array where dp[i] will be True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a subset with volume 0 is always possible (empty subset)

    # Iterate over each item
    for volume in volumes:
        # Traverse the dp array backwards to avoid using the same item multiple times
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be formed which is less than or equal to V
    max_occupied_volume = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied_volume = i
            break

    # The minimum remaining space is the total capacity minus the maximum occupied volume
    return V - max_occupied_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

